'use strict';
// Refresh mixed cached HTML/scripts before interacting with character saves.
(()=>{const release='0.42';if(document.documentElement.dataset.release===release)return;const target=new URL(location.href);if(target.searchParams.get('release')!==release){target.searchParams.set('release',release);location.replace(target.href)}})();

const SWORD_SKILLS={warriorMastery:{name:'Warrior Mastery',max:15,type:'passive'},ironBody:{name:'Iron Body',max:10,type:'passive'},slashBlast:{name:'Slash Blast',max:20,type:'active'},warriorLeap:{name:'Warrior Leap',max:10,type:'active'}};
const SWORD_DESCRIPTIONS={warriorMastery:'ฝึกพื้นฐานนักดาบ เพิ่มความเร็วเดิน แรงกระโดด HP และโอกาสต้านการกระเด็น',ironBody:'ร่างกายแข็งแกร่ง เพิ่ม HP และ DEF พร้อมลดความเสียหายที่ได้รับแบบติดตัว',slashBlast:'ฟันกวาดด้านหน้า โจมตีศัตรูได้สูงสุด 6 ตัว',warriorLeap:'กระโดดพุ่งไปด้านหน้ากลางอากาศ ใช้ได้หนึ่งครั้งก่อนแตะพื้น · กด Space ซ้ำกลางอากาศได้'};
let swordSwipes=[];
function emptySwordSkills(){return Object.fromEntries(Object.keys(SWORD_SKILLS).map(key=>[key,0]))}
function legacySwordSkills(raw){return raw&&!Object.keys(SWORD_SKILLS).some(key=>Object.hasOwn(raw,key))&&['powerBash','slash','hpBoost','defBoost'].some(key=>Object.hasOwn(raw,key))}
function validateSwordSkills(raw){const result=emptySwordSkills();if(raw===undefined)return result;if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('สกิลนักดาบไม่ถูกต้อง');for(const [key,max]of [['upperCharge',5],['leapAttack',1]]){const v=raw[key]??0;if(!Number.isInteger(v)||v<0||v>max)throw Error('สกิลที่ย้ายไม่ถูกต้อง')}if(legacySwordSkills(raw)){for(const [key,max]of [['powerBash',10],['slash',10],['hpBoost',5],['defBoost',5]]){const v=raw[key]??0;if(!Number.isInteger(v)||v<0||v>max)throw Error('สกิลเดิมไม่ถูกต้อง')}result.slashBlast=raw.slash||0;result.ironBody=(raw.hpBoost||0)+(raw.defBoost||0);return result}for(const key of Object.keys(result)){const v=raw[key]??0;if(!Number.isInteger(v)||v<0||v>(key==='ironBody'?20:SWORD_SKILLS[key].max))throw Error('ระดับ '+SWORD_SKILLS[key].name+' ไม่ถูกต้อง');result[key]=Math.min(v,SWORD_SKILLS[key].max)}return result}
function swordSkillInfo(key,lv){const base={cost:0,targets:0,multiplier:0,reach:140};if(key==='slashBlast')return {...base,multiplier:1.05+.05*lv,cost:6+Math.floor(lv/5),targets:6};if(key==='warriorLeap')return {...base,cost:4,speed:240+lv*14};return base}
function skillDescription(key,lv){if(key==='warriorMastery')return 'ความเร็ว +'+lv*3+'% · แรงกระโดด +'+Math.min(20,lv*2)+'% · HP +'+lv+'% · ต้านกระเด็น '+lv*2+'%';if(key==='ironBody')return 'HP +'+lv*2+'% · DEF +'+lv+' · ลดดาเมจ '+(lv*.5)+'%';const info=swordSkillInfo(key,Math.max(1,lv));if(key==='warriorLeap')return 'MP '+info.cost+' · ความเร็วพุ่ง '+info.speed+' · กลางอากาศ 1 ครั้ง';return Math.round(info.multiplier*100)+'% ATK · '+info.targets+' เป้าหมาย · MP '+info.cost+(key==='upperCharge'?' · แรงพุ่งขึ้น '+info.lift:key==='leapAttack'?' · โจมตีเมื่อลงพื้น':'')}
let selectedSwordSkill=null,skillTier=1;
function renderSwordSkillWindow(body){
 hideUpgradeTooltip();const definitions=skillTier===2?secondSkillTree():SWORD_SKILLS,ranks=skillTier===2?player.secondSkills:player.swordSkills;const points=skillTier===2?player.secondSP:player.sp;body.className='sword-skill-window';body.replaceChildren();
 const title=$('modalTitle');title.textContent=JOBS[player.job].name;const sp=document.createElement('strong');sp.id='swordSP';sp.textContent=(skillTier===2?'SP ขั้น 2 ':'SP ')+points;title.append(sp);
 const close=document.createElement('button');close.id='closeSkillBtn';close.className='close-skill';close.textContent='×';close.setAttribute('aria-label','ปิดหน้าสกิล');close.onclick=closeModal;body.append(close);
 const left=document.createElement('div');left.className='skill-left';const tabs=document.createElement('div');tabs.className='skill-tier-tabs';for(const tier of [1,2]){const tab=document.createElement('button');tab.textContent='สกิลขั้น '+tier;tab.disabled=tier===2&&player.job==='swordsman';tab.classList.toggle('selected',skillTier===tier);tab.onclick=()=>{skillTier=tier;selectedSwordSkill=null;renderSwordSkillWindow(body)};tabs.append(tab)}left.append(tabs);const list=document.createElement('div');list.className='sword-skill-list';
 for(const [key,skill]of Object.entries(definitions)){
  const lv=ranks[key],row=document.createElement('div');row.className='sword-skill-row'+(key===selectedSwordSkill?' selected':'');
  const select=document.createElement('button');select.className='skill-select';select.setAttribute('aria-label','ดู '+skill.name);select.setAttribute('aria-pressed',String(key===selectedSwordSkill));
  const name=document.createElement('strong');name.textContent=skill.name;const level=document.createElement('span');level.textContent='Lv. '+lv+' / '+skill.max;select.append(name,level);select.onclick=()=>{selectedSwordSkill=key;renderSwordSkillWindow(body);body.querySelector('[aria-label="ดู '+skill.name+'"]').focus()};
  const wrap=document.createElement('span');wrap.className='skill-upgrade-wrap';const plus=document.createElement('button');plus.className='skill-upgrade';plus.textContent='+';plus.setAttribute('aria-label','อัป '+skill.name);plus.disabled=points<1||lv>=skill.max||(skillTier===2&&!secondRequirementsMet(key));
  wrap.onmouseenter=()=>showSkillPreview(key,wrap);wrap.onmouseleave=()=>hideUpgradeTooltip(false);plus.onfocus=()=>showSkillPreview(key,wrap);
  plus.onclick=()=>{if(points<1||ranks[key]>=skill.max||(skillTier===2&&!secondRequirementsMet(key)))return;if(skillTier===2){player.secondSP--;player.secondSkills[key]++}else{player.sp--;player.swordSkills[key]++}save();renderSwordSkillWindow(body);updateUI()};wrap.append(plus);row.append(select,wrap);list.append(row);
 }
 left.append(list);const slots=document.createElement('div');slots.className='skill-binding-slots';
 for(const key of ['q','w','e','r']){const cell=document.createElement('label');cell.className='skill-binding-slot';const caption=document.createElement('span');caption.textContent=key.toUpperCase();const select=document.createElement('select');select.setAttribute('aria-label','สกิลช่อง '+key.toUpperCase());const empty=document.createElement('option');empty.value='';empty.textContent='ว่าง';select.append(empty);for(const [id,skill]of Object.entries(allSkillDefinitions())){if(skill.type!=='active'||!skillRank(id))continue;const option=document.createElement('option');option.value=id;option.textContent=skill.name;select.append(option)}select.value=player.skillSlots[key]||'';select.onchange=()=>{player.skillSlots[key]=select.value||null;save();updateSwordHUD()};cell.append(caption,select);slots.append(cell)}left.append(slots);body.append(left);
 if(!selectedSwordSkill)return;const right=document.createElement('div');right.className='skill-details';right.setAttribute('role','dialog');right.setAttribute('aria-label','รายละเอียดสกิล');const detailClose=document.createElement('button');detailClose.className='close-skill-detail';detailClose.textContent='×';detailClose.setAttribute('aria-label','ปิดรายละเอียดสกิล');detailClose.onclick=()=>{selectedSwordSkill=null;renderSwordSkillWindow(body)};right.append(detailClose);const key=selectedSwordSkill,skill=definitions[key],lv=ranks[key];
 const current=document.createElement('section');current.className='skill-detail-card';const heading=document.createElement('h3');heading.textContent=skill.name+' · Lv. '+lv+' / '+skill.max;const type=document.createElement('small');type.textContent=skill.type.toUpperCase();const desc=document.createElement('p');desc.textContent=skillTier===2?skill.desc+(skill.requires?' · ต้องมี '+Object.entries(skill.requires).map(([id,rank])=>secondSkillTree()[id].name+' Lv.'+rank).join(', '):''):SWORD_DESCRIPTIONS[key];const effect=document.createElement('p');effect.className='skill-effect';effect.textContent=(lv===0?'ยังไม่เรียน · Lv.1: ':'')+(skillTier===2?secondDescription:skillDescription)(key,Math.max(1,lv));current.append(heading,type,desc,effect);right.append(current);
 if(lv>0&&lv<skill.max){const next=document.createElement('section');next.className='skill-detail-card skill-next';const heading=document.createElement('h3');heading.textContent=skill.name+' · Lv. '+(lv+1)+' / '+skill.max;const type=document.createElement('small');type.textContent=skill.type.toUpperCase();const effect=document.createElement('p');effect.className='skill-effect';effect.textContent=(skillTier===2?secondDescription:skillDescription)(key,lv+1);const gain=document.createElement('p');gain.className='upgrade-gain';gain.textContent=(skillTier===2?secondDescription:skillDescription)(key,lv)+' → '+(skillTier===2?secondDescription:skillDescription)(key,lv+1);next.append(heading,type,effect,gain);right.append(next)}body.append(right);
}

function skillTargets(key,reach,targets){return monsters.filter(m=>!m.dead&&(m.x-player.x)*player.face>=-(monsterRadius(m)+8)&&(m.x-player.x)*player.face<reach+monsterRadius(m)&&player.y>m.y-monsterHeight(m)-15&&player.y<m.y+46).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x)).slice(0,targets)}
function strikeSwordSkill(key,lv){const info=swordSkillInfo(key,lv);player.swing=.25;swordSwipes.push({x:player.x,y:player.y-20,face:player.face,reach:info.reach,life:.28,key});for(const m of skillTargets(key,info.reach,info.targets))hitMonster(m,attackPower()*jobProfile().multiplier*info.multiplier);burst(player.x,player.y-15,'#c4eed9',12);tutorialMark('attack')}
let queuedAction=null;
function queueAction(action){if((player.cd.action||0)>0&&(player.cd.action||0)<=.22)queuedAction={action,life:.25};return false}
function tickQueuedAction(dt){if(!queuedAction)return;queuedAction.life-=dt;if(queuedAction.life<=0){queuedAction=null;return}if((player.cd.action||0)<=0){const next=queuedAction.action;queuedAction=null;if(next==='attack')act('attack');else if(SWORD_SKILLS[next])castSwordSkill(next);else castSecondSkill(next)}}
function actionDelay(id){const base={attack:jobProfile().cooldown,slashBlast:.42,warriorLeap:.2,brandish:.45,flashSlash:.4,divineSwing:.45,pageOrder:.48,spearPulling:.45,beholderShock:.5}[id]||.4;return Math.max(id==='warriorLeap'?.2:.32,base*(1-(player.secondSkills?.weaponAcceleration||0)*.025))}
function beginActionDelay(id){player.cd.action=actionDelay(id);player.swing=Math.max(player.swing||0,Math.min(.5,player.cd.action))}
function castSwordSkill(key){if((player.cd.action||0)>0||paused||screen!=='play'||run?.finished||SWORD_SKILLS[key]?.type!=='active')return false;const lv=player.swordSkills?.[key]||0;if(!lv)return false;const info=swordSkillInfo(key,lv);if(player.mp<info.cost)return false;if(key==='warriorLeap'&&(player.ground||player.climbing||player.airLeapUsed))return false;beginActionDelay(key);player.mp-=info.cost;if(key==='warriorLeap'){player.airLeapUsed=true;player.vy=Math.max(player.vy,-60);player.dashV=player.face*info.speed;player.dashTime=.22;burst(player.x,player.y-15,'#bfdccf',10)}else strikeSwordSkill(key,lv);tone(340,.13,'triangle');updateUI();return true}
function usePotion(kind){if(paused||screen!=='play'||run?.finished)return false;const maximum=kind==='hp'?maxHP():maxMP(),cd=kind==='hp'?'hpPotion':'mpPotion';if(player[kind]>=maximum||player.cd[cd]>0||!(player.consumables?.[cd]>0))return false;player.consumables[cd]--;const value=Math.min(maximum-player[kind],Math.ceil(maximum*.35));player[kind]+=value;player.cd[cd]=2;burst(player.x,player.y-20,kind==='hp'?'#f5a599':'#a3d3ff',12);tone(kind==='hp'?610:760,.12);save();updateUI();return true}
function updateSwordHUD(){const slots=player.skillSlots||{},learned={...player.swordSkills,...player.secondSkills};for(const key of ['q','w','e','r']){const button=$('hotbar'+key.toUpperCase());if(!button)continue;const id=slots[key],skill=id?allSkillDefinitions()[id]:null;button.disabled=!skill||!learned[id];button.title=skill?skill.name+' · Lv.'+(learned[id]||0):'ว่าง';const caption=button.querySelector('span');if(caption)caption.textContent=key.toUpperCase()+'['+(skill?skill.name:'-----')+']';const icon=button.querySelector('.hotbar-icon');if(icon)icon.textContent=id==='powerBash'?'⌁':id==='slash'?'╱':''}for(const [kind,id]of [['hp','hpPotionBtn'],['mp','mpPotionBtn']]){const cd=kind==='hp'?'hpPotion':'mpPotion',button=$(id),label=$(kind+'PotionCD');if(button){const stock=player.consumables?.[cd]??0;button.disabled=player.cd[cd]>0||stock===0;button.classList.toggle('empty-potion',stock===0);button.title='';let text=button.querySelector('.potion-kind');if(!text){text=document.createElement('b');text.className='potion-kind';button.append(text)}text.textContent=kind.toUpperCase();let count=button.querySelector('.potion-count');if(!count){count=document.createElement('strong');count.className='potion-count';button.append(count)}count.textContent=stock;button.setAttribute('aria-label','ยา '+kind.toUpperCase()+' '+(kind==='hp'?'Z':'X')+' · '+stock+' ขวด');button.onmouseenter=()=>showItemDetail(button,POTION_ITEMS[cd],stock);button.onmouseleave=()=>hideUpgradeTooltip(false)}if(label)label.textContent=player.cd[cd]>0?player.cd[cd].toFixed(1):''}}

function tickSwordSwipes(dt){player.dashTime=Math.max(0,(player.dashTime||0)-dt);if(player.ground)player.airLeapUsed=false;for(const swipe of swordSwipes)swipe.life-=dt;swordSwipes=swordSwipes.filter(s=>s.life>0)}
function drawSwordSwipes(){for(const s of swordSwipes){ctx.save();ctx.translate(s.x,s.y);ctx.scale(s.face,1);ctx.globalAlpha=Math.min(1,s.life*5);ctx.strokeStyle=s.key==='powerBash'?'#ffe1a0':'#d2f7c4';ctx.lineWidth=s.key==='powerBash'?7:4;ctx.beginPath();for(let i=0;i<9;i++){const angle=-1.05+i*.26,x=Math.cos(angle)*s.reach*.75,y=Math.sin(angle)*36;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.restore()}}
function validateSkillSlots(raw,skills,secondSkills={},job='swordsman'){const definitions={...SWORD_SKILLS,...(SECOND_SKILLS[job]||{})},learned={...skills,...secondSkills};const slots={q:null,w:null,e:null,r:null};if(raw===undefined)return slots;if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('ช่องสกิลไม่ถูกต้อง');for(const key of Object.keys(slots)){let value=raw[key]??null;if(value==='slash')value='slashBlast';if(['powerBash','upperCharge','leapAttack'].includes(value))value=null;if(value!==null&&definitions[value]?.type==='passive')value=null;if(value!==null&&(!definitions[value]||definitions[value].type!=='active'||!learned[value]))throw Error('สกิลในช่อง '+key+' ไม่ถูกต้อง');slots[key]=value}return slots}
function castAssignedSkill(slot){const skill=player.skillSlots?.[slot];if(skill&&(player.cd.action||0)>0)return queueAction(skill);return skill?(SWORD_SKILLS[skill]?castSwordSkill(skill):castSecondSkill(skill)):false}
window.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-skill-slot]').forEach(b=>b.onclick=()=>castAssignedSkill(b.dataset.skillSlot));if($('hpPotionBtn'))$('hpPotionBtn').onclick=()=>usePotion('hp');if($('mpPotionBtn'))$('mpPotionBtn').onclick=()=>usePotion('mp')});

const POTION_ITEMS={hpPotion:{name:'ยาเพิ่ม HP',kind:'hp',description:'ฟื้นฟู HP 35% ของ HP สูงสุด · ใช้ด้วย Z · พักการใช้ยา 2 วินาที'},mpPotion:{name:'ยาเพิ่ม MP',kind:'mp',description:'ฟื้นฟู MP 35% ของ MP สูงสุด · ใช้ด้วย X · พักการใช้ยา 2 วินาที'}};
function validateConsumables(raw){if(raw===undefined)return {hpPotion:10,mpPotion:10};if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('ข้อมูลยาไม่ถูกต้อง');const out={};for(const key of Object.keys(POTION_ITEMS)){const value=raw[key]??0;if(!Number.isInteger(value)||value<0||value>9999)throw Error('จำนวนยาไม่ถูกต้อง');out[key]=value}return out}
function showItemDetail(anchor,item,count,pinned=false){showUpgradeTooltip(anchor,item.name||item.item,[],item.description+(count!==undefined?'\nจำนวน '+count+' ขวด':''),pinned)}

function removedSwordPointRefund(raw){if(!raw||legacySwordSkills(raw))return 0;return Math.max(0,(raw.ironBody||0)-10)+(raw.upperCharge||0)+(raw.leapAttack||0)}
